INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Projektablaufplan immer statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Kann an Änderungen angepasst werden"}, {"text": "Ja", "correct": false, "because": "Flexibel bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Projektablaufplans?', 3, '[{"text": "Projektstruktur visualisieren", "correct": true, "because": "Zeigt Phasen und Meilensteine"}, {"text": "Code schreiben", "correct": false, "because": "Nicht Programmierung"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Planungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente enthält ein Projektablaufplan typischerweise?', 5, '[{"text": "Meilensteine", "correct": true, "because": "Markieren wichtige Punkte"}, {"text": "Zeitplan", "correct": true, "because": "Definiert Dauer"}, {"text": "Farbcodes", "correct": false, "because": "Nur gestalterisch"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant für Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Projektablaufplan zeigt Abhängigkeiten. b) Er ersetzt die Projektsteuerung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Werkzeug, nicht Steuerung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Projektablaufplans?', 4, '[{"text": "Ressourcenplanung", "correct": false, "because": "Bestimmt Aufgabenverteilung"}, {"text": "Meilensteine", "correct": false, "because": "Strukturieren Projekt"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Projektablaufplan nur für IT-Projekte genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Projektarten geeignet"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Erstellung eines Projektablaufplans?', 3, '[{"text": "Gantt-Diagramm", "correct": true, "because": "Visualisiert Zeitplan"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet für Visualisierung"}, {"text": "Manuelle Skizzen", "correct": false, "because": "Software effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Projektablaufplan?', 5, '[{"text": "Übersichtlichkeit", "correct": true, "because": "Zeigt Abläufe klar"}, {"text": "Koordination", "correct": true, "because": "Synchronisiert Team"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Einmalige Nutzung", "correct": false, "because": "Kontinuierlich genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Projektablaufplan zeigt Meilensteine. b) Er ersetzt Teammeetings. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Projektablaufplan?', 4, '[{"text": "Zeitplan", "correct": false, "because": "Definiert Ablauf"}, {"text": "Ressourcen", "correct": false, "because": "Bestimmen Einsatz"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Projektablaufplan dasselbe wie ein Gantt-Diagramm?', 2, '[{"text": "Nein", "correct": true, "because": "Gantt-Diagramm ist Darstellungsform"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen einen Projektablaufplan?', 4, '[{"text": "Projektziele", "correct": true, "because": "Leiten Aufgaben"}, {"text": "Ressourcenverfügbarkeit", "correct": true, "because": "Beeinflusst Zeitplan"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Projektablaufplan immer unveränderlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassbar bei Änderungen"}, {"text": "Ja", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung eines Projektablaufplans?', 3, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Maximale Details", "correct": false, "because": "Kann überladen"}, {"text": "Manuelle Zeichnung", "correct": false, "because": "Tools effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Projektablaufplan zeigt Abhängigkeiten. b) Er ist nur für Manager relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) betrifft ganzes Team"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen die Erstellung eines Projektablaufplans?', 5, '[{"text": "MS Project", "correct": true, "because": "Visualisiert Zeitpläne"}, {"text": "Jira", "correct": true, "because": "Unterstützt Agile Planung"}, {"text": "Bildbearbeitung", "correct": false, "because": "Kein Planungstool"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet für Visualisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Projektablaufplan unwichtig?', 3, '[{"text": "Zeitplan", "correct": false, "because": "Definiert Ablauf"}, {"text": "Meilensteine", "correct": false, "because": "Markieren Fortschritt"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Projektablaufplan für agile Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel anpassbar"}, {"text": "Nein", "correct": false, "because": "Auch in Agile nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Projektablaufplan nur Zeitpläne?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Abhängigkeiten und Ressourcen"}, {"text": "Ja", "correct": false, "because": "Umfassender"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Projektablaufplan?', 4, '[{"text": "Planung einer Softwareentwicklung", "correct": true, "because": "Strukturiert Abläufe"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Projektplanung"}, {"text": "Bildbearbeitung", "correct": false, "because": "Kreative Aufgabe"}]');
